#include <iostream>
using namespace std;

class Animal {
public:
  virtual void sound() {
    cout << "..." << endl;
  }
  virtual ~Animal() {}
};

class Cow : public Animal {
public:
  void sound() override {
    cout << "Moo" << endl;
  }
};

class Dog : public Animal {
public:
  void sound() override {
    cout << "Woof" << endl;
  }
};

int main() {
  Cow c;
  Dog d;
  Animal* zoo[2] = {&c, &d};
  for (Animal* a : zoo) {
    a->sound();
  }
  return 0;
}

