#include <iostream>
using namespace std;

class Shape {
public:
  virtual double area() = 0;
  virtual ~Shape() {}
};

class Square : public Shape {
  double side;
public:
  Square(double s) : side(s) {}
  double area() override {
    return side * side;
  }
};

int main() {
  Square sq(3);
  Shape& s = sq;
  cout << s.area() << endl;
  return 0;
}

