int divide(int a, int b) {
  if (b == 0) throw 0;
  return a / b;
}

int main() {
  try {
    cout << divide(10, 2) << endl;
    cout << divide(1, 0) << endl;
  } catch (int) {
    cout << "Cannot divide by zero" << endl;
  }
  return 0;
