#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
  vector<int> v = {40, 10, 30, 20};
  sort(v.begin(), v.end());
  for (int x : v) cout << x << " ";
  cout << endl;
  sort(v.begin(), v.end(), [](int a, int b) { return a > b; });
  for (int x : v) cout << x << " ";
  cout << endl;
  reverse(v.begin(), v.end());
  cout << v[0] << endl;
  return 0;
}

